properties.property:
[
{
   "text": "You step into a musty crypt. Immediately, you sense that despite its somber appearance, the air is electric with pulsing mana. As you enter, a booming voice rings out from nowhere.

'YOU ENTER THE CRYPT WHICH IMPRISONS THOSE WHO BROKE THE RULES OF BOTH MAGIC AND DEATH! TURN BACK!'",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "A skittering little homunculus stands ahead, frantically speed-reading from a mountain of notes it has clearly looked over a great many times before.

'Where is it! WHERE IS IT?!' it cries out. Then, upon seeing you it yells 'TELL ME YOUR SECRETS!!!'",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]

